/* edges details for region "math", loaded on demand by atlas/app.js (ATLAS.loadDetails). */
window.ATLAS.addDetails("math.edges",{"edges":{
"binary-search:exp-log":{"type":"foundation","label":{"zh":"砍半次数就是对数","en":"The halving count is the logarithm"},"reason":{"zh":"二分查找每步砍掉一半，n 个数约 log₂n 步：对数数的正是“砍几次到 1”；反过来，汉诺塔的指数增长就是对数的逆过程。","en":"Binary search halves each step, taking about log₂n steps for n items: the logarithm counts exactly \"how many halvings to 1\"; reversed, the Tower of Hanoi's exponential growth is the logarithm's inverse."},"source":"../computing/algorithms/recursion-divide/#step3"},
"chicken-rabbit:slope":{"type":"representation","label":{"zh":"总量随兑换匀速上升","en":"Total rises steadily per swap"},"reason":{"zh":"每换一只总脚数加同样的 2，所以脚数对兔数的图是一条斜线，交点即答案，这就是一次函数的图像。","en":"Each swap adds the same 2 feet, so feet against rabbits is a straight line whose crossing is the answer, which is a linear function's graph."},"source":"../math/arithmetic/chicken-rabbit/#step2"},
"circle-intro:unit-circle":{"type":"foundation","label":{"zh":"圆是单位圆的起点","en":"The circle underlies the unit circle"},"reason":{"zh":"先认识半径、周长与 π，再把半径取为 1，就得到用来定义角和三角函数的单位圆。","en":"Once radius, circumference and π are understood, taking the radius as 1 gives the unit circle used to define angles and trigonometric functions."},"source":"../math/geometry/circle-intro/#step3"},
"clock-angles:unit-circle":{"type":"application","label":{"zh":"角度随时间匀速增长","en":"Angle grows steadily with time"},"reason":{"zh":"两根针都是绕圆心匀速转动，转过的角度与时间成正比，钟面就是一个带刻度的单位圆。","en":"Both hands turn about the centre at a constant rate, so angle is proportional to time and the dial is a graduated circle."},"source":"../math/geometry/clock-angles/#step0"},
"cnn-feature-maps:derivative":{"type":"connection","label":{"zh":"边缘核是差分，近似导数","en":"Edge kernels are differences, approximating derivatives"},"reason":{"zh":"左负右正的边缘核计算左右像素之差，是对图像亮度求导数的离散近似，所以平坦处输出 0。","en":"A left-negative, right-positive edge kernel computes the difference between neighbouring pixels, a discrete approximation of the brightness derivative, so flat regions give 0."},"source":"../computing/ml/cnn-feature-maps/#step2"},
"complex:fourier":{"type":"representation","label":{"zh":"表示旋转分量","en":"represents rotating components"},"reason":{"zh":"欧拉公式把正弦和余弦写成复指数的组合，复数傅里叶变换由此统一表示正、负频率分量。","en":"Euler’s formula expresses sine and cosine as combinations of complex exponentials, allowing the complex Fourier transform to represent positive and negative frequencies together."},"source":"https://www.dspguide.com/CH31.PDF#page=3"},
"compound-interest:montecarlo":{"type":"connection","label":{"zh":"把确定的账换成随机的账","en":"From a certain ledger to a random one"},"reason":{"zh":"复利假设利率确定；真实回报有波动时，可以用大量随机抽样估计终值的分布，这是蒙特卡洛的典型用法。","en":"Compounding assumes a certain rate; when real returns fluctuate, many random draws can estimate the distribution of the final value, a typical use of Monte Carlo."},"source":"../investment/rates/compound-interest/#step4"},
"compound-interest:variance":{"type":"connection","label":{"zh":"风险让期望不等于全部","en":"Risk means the expected value is not everything"},"reason":{"zh":"确定利率下终值只有一个数；回报有波动时需要同时看平均和方差，同样的平均增长率下波动越大，复利终值越低。","en":"At a certain rate the final value is a single number; with fluctuating returns you need both the mean and the variance, and for the same average return more volatility lowers the compounded result."},"source":"../investment/rates/compound-interest/#step5"},
"conic-sections:net-force":{"type":"application","label":{"zh":"轨道是圆锥曲线","en":"Orbits are conics"},"reason":{"zh":"平方反比引力下，物体的轨道是以引力中心为焦点的圆锥曲线，离心率 e 决定它是椭圆、抛物线还是双曲线。","en":"Under an inverse-square force a body’s orbit is a conic with the attracting centre at a focus, and the eccentricity e decides whether it is an ellipse, parabola or hyperbola."},"source":"../math/geometry/conic-sections/#step1"},
"convolution:derivative":{"type":"foundation","label":{"zh":"差分就是离散导数","en":"Differences are discrete derivatives"},"reason":{"zh":"边缘核对邻居相减，算的正是离散差分；差分是导数在格点上的化身，所以边缘核天生就是导数探测器。","en":"Edge kernels subtract neighbours, computing exactly discrete differences; a difference is the derivative incarnated on a grid, so edge kernels are born derivative detectors."},"source":"../computing/ml/cnn-feature-maps/#step2"},
"counting-permutations:bayes":{"type":"connection","label":{"zh":"频数表里的计数","en":"Counts in a frequency table"},"reason":{"zh":"贝叶斯公式的自然频数写法就是数“符合条件的人”占“满足条件的人”的比例，用的正是同样的计数思想。","en":"The natural-frequency form of Bayes’ rule counts the people who meet a condition as a share of those in a group, the same counting idea."},"source":"../probability/basics/counting-permutations/#step4"},
"counting-permutations:probability":{"type":"foundation","label":{"zh":"等可能时概率靠数","en":"With equally likely outcomes, probability is counting"},"reason":{"zh":"等可能结果下概率就是符合条件的方法数除以总方法数，所以排列组合是计算古典概率的基础。","en":"With equally likely outcomes, probability is favourable ways divided by total ways, so permutations and combinations underlie classical probability."},"source":"../probability/basics/counting-permutations/#step5"},
"derivative:backpropagation":{"type":"application","label":{"zh":"斜率变成每个权重的梯度","en":"slopes become per-weight gradients"},"reason":{"zh":"把权重推一小步看损失变化就是割线斜率，ε 趋于 0 时成为导数；反向传播用链式法则一次算出所有这些导数。","en":"Nudging a weight and watching the loss gives a secant slope that becomes the derivative as ε → 0; backpropagation computes all these derivatives at once with the chain rule."},"source":"../computing/ml/backpropagation/#step1"},
"derivative:capacitor":{"type":"application","label":{"zh":"把电流读成电压变化率","en":"reads current as voltage rate"},"reason":{"zh":"对恒定理想电容，q=Cv且i=dq/dt，所以i=C·dv/dt；电流流入电压标正的端子。零电流保持已有电压；这不是漏电或电阻充电模型，也不是必修顺序。","en":"For constant ideal capacitance, q=Cv and i=dq/dt give i=C·dv/dt, with current entering the voltage-positive terminal. Zero current preserves existing voltage; this is not leakage or resistive charging, nor a mandatory learning order."},"source":"https://openstax.org/books/university-physics-volume-2/pages/9-1-electrical-current"},
"derivative:contour-lines":{"type":"application","label":{"zh":"疏密就是变化率","en":"Spacing is a rate of change"},"reason":{"zh":"相邻等高线海拔差固定，水平间距越短说明每走一米海拔变化越快，也就是坡度（导数的大小）越大。","en":"Neighbouring contours differ by a fixed height, so a shorter horizontal gap means altitude changes faster per metre travelled, i.e. a larger slope (the size of the derivative)."},"source":"../earth/geo/contour-lines/#step1"},
"derivative:electromagnetic-induction":{"type":"application","label":{"zh":"电压是磁通量的变化率","en":"Voltage is the rate of change of flux"},"reason":{"zh":"磁通量变化越快，感应电动势越大——导数就是“变化快慢”的量度，所以法拉第定律写成 ε = −N dΦ/dt：它量的正是磁通量被推着走的速度。","en":"The faster the flux changes, the larger the induced emf — a derivative is exactly the measure of 'how fast it changes', so Faraday's law is written ε = −N dΦ/dt: it measures the speed at which the flux is being pushed."},"source":"../physics/electromagnetism/electromagnetic-induction/#step1"},
"derivative:enzymes":{"type":"connection","label":{"zh":"曲线的斜率与渐近线","en":"Slope and asymptote of a curve"},"reason":{"zh":"米氏曲线在 [S] = 0 处斜率为 Vmax/Kₘ，在大 [S] 处趋于水平的渐近线 Vmax。","en":"The Michaelis–Menten curve has slope Vmax/Kₘ at [S] = 0 and flattens toward the asymptote Vmax at large [S]."},"source":"../biology/cells/enzymes/#step1"},
"derivative:molecular-shapes":{"type":"application","label":{"zh":"力是能量的下坡斜率","en":"Force is the downhill slope of energy"},"reason":{"zh":"第 1 步每个点沿能量下降最快的方向走一小步，力就是排斥能的负梯度（导数的推广）。","en":"In step 1 each point steps along the direction of steepest energy descent; the force is the negative gradient of the repulsion energy, a generalised derivative."},"source":"../chemistry/matter/molecular-shapes/#step1"},
"derivative:newton-laws":{"type":"application","label":{"zh":"加速度是速度的变化率","en":"Acceleration is the rate of change of velocity"},"reason":{"zh":"第 0 步把加速度当作速度每秒的变化量，频闪图里相邻残影的间距增加量就是它的直观样子。","en":"Step 0 treats acceleration as the change of velocity per second, and the growth of the gaps between ghosts is its visual form."},"source":"../physics/mechanics/newton-laws/#step0"},
"derivative:newton-method":{"type":"application","label":{"zh":"切线斜率用来找零点","en":"Tangent slope used to find zeros"},"reason":{"zh":"第 0 步用导数 f′(x₀) 作切线，切线与横轴的交点就是下一个猜测。","en":"Step 0 uses the derivative f′(x₀) to draw the tangent, and its x-axis crossing is the next guess."},"source":"../math/calculus/newton-method/#step0"},
"derivative:oscillation":{"type":"representation","label":{"zh":"描述运动的变化率","en":"describes motion rates"},"reason":{"zh":"本振子的可微位置 x(t) 给出 v=dx/dt、a=dv/dt；有方向的速度可以为负，速率是 |v|。微分描述运动，不是产生运动的物理原因。","en":"For this oscillator, v=dx/dt and a=dv/dt. Signed velocity can be negative; speed is |v|. Differentiation describes motion rather than causing it."},"source":"../math/calculus/derivative/#step0"},
"derivative:taylor-series":{"type":"application","label":{"zh":"系数 = 各阶导数 ÷ k!","en":"Coefficients are derivatives over k!"},"reason":{"zh":"第 3 步由函数值、斜率、弯曲程度等各阶导数在中心处一致，得到 cₖ = f⁽ᵏ⁾(a)/k!。","en":"Step 3 matches the value, slope, curvature and higher derivatives at the centre, giving cₖ = f⁽ᵏ⁾(a)/k!."},"source":"../math/calculus/taylor-series/#step3"},
"derivative:titration-curves":{"type":"application","label":{"zh":"突跃就是斜率最大处","en":"The leap is where the slope peaks"},"reason":{"zh":"等当点处 dpH/dV 最大，所以判断终点就是找曲线斜率的峰。","en":"dpH/dV is largest at the equivalence point, so locating the end point means finding the peak of the curve's slope."},"source":"../chemistry/solutions/titration-curves/#step1"},
"eigen:conic-sections":{"type":"connection","label":{"zh":"主轴把 xy 项消掉","en":"Principal axes remove the xy term"},"reason":{"zh":"二次曲线 Ax² + Bxy + Cy² = 1 的 xy 项来自二次型矩阵不是对角的；换到特征向量方向（主轴）后矩阵对角化，曲线就摆正，椭圆或双曲线的半轴长由特征值决定。","en":"The xy term in Ax² + Bxy + Cy² = 1 appears because the quadratic form’s matrix is not diagonal; in the eigenvector directions (the principal axes) it diagonalises, the curve straightens, and the eigenvalues set the semi-axis lengths of the ellipse or hyperbola."},"source":"../math/geometry/conic-sections/#step4"},
"eigen:markov-chains":{"type":"connection","label":{"zh":"特征值决定收敛速度","en":"Eigenvalues set the convergence speed"},"reason":{"zh":"转移矩阵的稳态是特征值 1 对应的左特征向量，其余特征值的大小 |λ₂| 决定与稳态的距离按 |λ₂|ⁿ 衰减。","en":"The steady state is the left eigenvector for eigenvalue 1, and the size of the next eigenvalue |λ₂| makes the distance to it decay like |λ₂|ⁿ."},"source":"../probability/stochastic/markov-chains/#step4"},
"eigen:pagerank":{"type":"application","label":{"zh":"幂迭代求主特征向量","en":"power iteration for the dominant eigenvector"},"reason":{"zh":"PageRank 就是转移矩阵（含瞬移）的稳态向量，用反复乘矩阵的幂迭代即可得到，和特征向量页的幂迭代是同一个算法。","en":"PageRank is the stationary vector of the transition matrix (with teleporting), obtained by repeated multiplication, which is the same algorithm as power iteration on the eigenvector page."},"source":"../computing/algorithms/pagerank/#step2"},
"eigen:probability":{"type":"connection","label":{"zh":"稳态分布就是特征向量","en":"The steady distribution is an eigenvector"},"reason":{"zh":"稳态 π 满足 πP = π：它正是转移矩阵特征值 1 的特征向量；随机游走的长期比例，本质上是一个特征问题。","en":"The steady state π satisfies πP = π — it is exactly the eigenvector of the transition matrix for eigenvalue 1; a random walk's long-run shares are, at heart, an eigen-problem."},"source":"../probability/stochastic/markov-chains/#step4"},
"eigen:variance":{"type":"application","label":{"zh":"找出协方差主方向","en":"finds principal covariance directions"},"reason":{"zh":"对协方差矩阵，特征向量给出互相正交的主方向，特征值给出沿这些方向的方差。","en":"For a covariance matrix, an orthonormal eigenbasis gives principal directions, and eigenvalues give variances along them."},"source":"../math/linear-algebra/eigenvectors/#step5"},
"electric-fields:molecular-shapes":{"type":"application","label":{"zh":"同号电荷互相排斥","en":"Like charges repel"},"reason":{"zh":"电子对在球面上被 1/r² 的静电斥力推开，排成最低能量的队形。","en":"Electron pairs on the sphere are pushed apart by a 1/r² electrostatic repulsion and settle into the lowest-energy arrangement."},"source":"../chemistry/matter/molecular-shapes/#step1"},
"electric-fields:periodic-trends":{"type":"application","label":{"zh":"核电荷吸引电子","en":"Nuclear charge attracts electrons"},"reason":{"zh":"有效核电荷越大，对外层电子的静电吸引越强，半径越小。","en":"A larger effective nuclear charge attracts outer electrons more strongly and shrinks the radius."},"source":"../chemistry/matter/periodic-trends/#step2"},
"embeddings:attention-mechanism":{"type":"application","label":{"zh":"输入给注意力","en":"input to attention"},"reason":{"zh":"注意力对每个词的向量做查询、键、值运算，词向量是这些运算的起点；这里只说明衔接，不涉及训练细节。","en":"Attention computes queries, keys and values from each word's vector, so embeddings are the starting point; this edge only states the hand-off and says nothing about training details."},"source":"../computing/ml/embeddings/#step4"},
"energy-pyramid:integral":{"type":"connection","label":{"zh":"年产量是速率的累积","en":"Annual production is an accumulated rate"},"reason":{"zh":"每年产量 = 生物量 × 更替率，说明某一时刻的存量与单位时间的流量是两个不同的量。","en":"Annual production = biomass × turnover, showing that a stock at one moment and a flow per unit time are different quantities."},"source":"../biology/ecology/energy-pyramid/#step3"},
"exp-log:rsa-encryption":{"type":"application","label":{"zh":"位数每加 1 步数乘 10","en":"One more digit, ten times the work"},"reason":{"zh":"第 0 步的纵轴是对数刻度：试除法的步数随位数指数增长，正是指数与对数页讲的“乘出来是指数”。","en":"Step 0’s vertical axis is logarithmic: trial-division work grows exponentially with digits, the “multiplying makes exponentials” of the exp-log page."},"source":"../computing/systems/rsa-encryption/#step0"},
"expected-value:montecarlo":{"type":"application","label":{"zh":"长期平均逼近期望","en":"Long-run averages approach it"},"reason":{"zh":"重复抽样的平均值按 σ/√n 逼近期望，蒙特卡洛估计就是用这个事实把平均值当作期望的估计。","en":"The average of repeated draws approaches the expectation with error about σ/√n, the fact Monte Carlo estimation uses to take the average as an estimate of the expectation."},"source":"../probability/basics/expected-value/#step2"},
"expected-value:variance":{"type":"connection","label":{"zh":"期望之外还要看波动","en":"Beyond the mean, the spread"},"reason":{"zh":"保险与彩票的例子说明期望相同或更差时，波动（方差）仍会改变决定，所以期望和方差要一起看。","en":"The insurance and lottery examples show that with equal or worse expectation the spread (variance) can still change the decision, so expectation and variance go together."},"source":"../probability/basics/expected-value/#step4"},
"game-theory:externalities":{"type":"connection","label":{"zh":"公地悲剧是多人博弈","en":"The commons is a many-player game"},"reason":{"zh":"每个牧民各自最优的选择合起来使总利润下降，这是纳什均衡劣于合作结果的又一例。","en":"Each herder’s individually best choice adds up to lower total profit, another case of a Nash equilibrium worse than the cooperative outcome."},"source":"../math/applied/externalities/#step4"},
"inequalities:slope":{"type":"connection","label":{"zh":"负的斜率会翻转次序","en":"A negative slope reverses order"},"reason":{"zh":"乘负数使数轴上的次序颠倒，与一次函数中斜率为负时直线向下倾斜是同一回事。","en":"Multiplying by a negative reverses order on the number line, the same fact as a negative slope making a line fall."},"source":"../math/algebra/inequalities/#step3"},
"integral:inductor":{"type":"application","label":{"zh":"把电压面积换成电流改变量","en":"maps voltage area to current change"},"reason":{"zh":"恒定理想L、被动端口符号下，∫vL dt=L[iL(b)−iL(a)]。有符号伏秒决定电流改变量，不是能量；重复周期净面积为零时电流回到起值，不必为零。暂态区间不要求平衡。","en":"For constant ideal L with passive terminal signs, ∫vL dt=L[iL(b)−iL(a)]. Signed voltseconds determine current change, not energy. Zero net area over a repeating period returns current to its initial value, not necessarily zero. Transient intervals need not balance."},"source":"https://wiki.analog.com/university/courses/electronics/buck_converter_basics"},
"integral:oscillation":{"type":"application","label":{"zh":"累加往返的位移","en":"accumulates signed travel"},"reason":{"zh":"本振子往返一周回到同一位置，正负速度贡献抵消，位移为零；路程为4A。交换积分限使有向积分变号，按时间先后的路程仍非负。","en":"One oscillator cycle returns to the same position: opposite velocity contributions cancel, giving zero displacement but distance4A. Reversing limits changes an oriented integral’s sign; chronological path length remains nonnegative."},"source":"https://openstax.org/books/calculus-volume-1/pages/5-2-the-definite-integral"},
"integral:work-energy":{"type":"application","label":{"zh":"对位移累加力的作用","en":"integrates force over displacement"},"reason":{"zh":"一维功沿路径积 F dx，单位 N·m=J；a、b 可选时间端点，但积分变量 x 是位移，不是时间。弹簧往返时各段可做正功或负功。","en":"One-dimensional work integrates F dx along the path, in N·m=J. Time bounds a,b choose endpoint positions, but the integration variable x is displacement, not time. Spring work can be positive or negative along different legs."},"source":"https://openstax.org/books/university-physics-volume-1/pages/7-1-work"},
"intervals-fences:patterns-sequences":{"type":"connection","label":{"zh":"同属“数形对齐”","en":"Both align counts with shapes"},"reason":{"zh":"火柴链的火柴数与植树的棵数都要先数“段”再补起头的一个，差一的来源相同。","en":"Matchstick totals and tree counts both count the repeated pieces first and then add the starter, so the off-by-one has the same source."},"source":"../math/arithmetic/intervals-fences/#step1"},
"inverse-proportion:slope":{"type":"connection","label":{"zh":"与一次函数对照","en":"A contrast with linear change"},"reason":{"zh":"一次函数每步增加同样多（斜率），反比例是每步乘同样的倍数的倒数；用“比值不变 / 乘积不变”区分。","en":"A linear function adds the same amount each step (the slope), while inverse proportion keeps the product fixed; “constant ratio versus constant product” tells them apart."},"source":"../math/algebra/inverse-proportion/#step3"},
"isomers:activation-energy":{"type":"connection","label":{"zh":"能垒决定能不能转","en":"The barrier decides whether it can turn"},"reason":{"zh":"单键的扭转能垒小、双键的大，e^(−ΔE/RT) 决定室温下能否越过，这就是顺反异构能分开的原因。","en":"Torsion barriers are small for single bonds and large for double bonds, and e^(−ΔE/RT) decides whether they can be crossed at room temperature, which is why cis and trans can be separated."},"source":"../chemistry/matter/isomers/#step4"},
"isomers:molecular-shapes":{"type":"connection","label":{"zh":"连接不同，形状也不同","en":"Different connection, different shape"},"reason":{"zh":"异构体的骨架决定每个原子周围的键如何排布，沿用分子构型页的电子对排斥。","en":"A skeleton fixes how bonds sit around each atom, following the electron-pair repulsion of the molecular-shapes lesson."},"source":"../chemistry/matter/isomers/#step0"},
"laplace:fourier":{"type":"connection","label":{"zh":"在收敛条件下限制到虚轴","en":"restricts to the imaginary axis when convergent"},"reason":{"zh":"当拉普拉斯变换的收敛域包含虚轴时，在 s = iω 处取值可得到傅里叶变换。","en":"If the Laplace region of convergence contains the imaginary axis, evaluating at s = iω gives the Fourier transform."},"source":"../signal/transforms/laplace/#step2"},
"laplace:poles":{"type":"representation","label":{"zh":"揭示指数模式","en":"reveals exponential modes"},"reason":{"zh":"对本课中的有理变换，极点的实部关联增长或衰减，虚部关联振荡；还要结合因果性和收敛域判断稳定性。","en":"For the rational transforms in this lesson, pole real parts describe growth or decay and imaginary parts describe oscillation; stability also depends on causality and convergence."},"source":"../signal/transforms/laplace/#step4"},
"magnets:vectors":{"type":"representation","label":{"zh":"场是每点一个向量","en":"A field is a vector at every point"},"reason":{"zh":"指南针和铁屑小线段显示的是每个位置磁场的方向和大小，也就是给每个点配一个向量。","en":"The compasses and filings show the direction and size of the field at each position, that is, a vector assigned to every point."},"source":"../physics/electromagnetism/magnets/#step3"},
"moon-phases:unit-circle":{"type":"application","label":{"zh":"位置角决定亮面比例","en":"Position angle sets the lit fraction"},"reason":{"zh":"月亮在轨道上的角度 θ 通过 cos θ 决定亮面的比例，这是单位圆上余弦的直接应用。","en":"The Moon's orbital angle θ sets the lit fraction through cos θ, a direct use of the cosine on the unit circle."},"source":"../earth/astronomy/moon-phases/#step1"},
"net-force:vectors":{"type":"application","label":{"zh":"力的平衡是向量和为零","en":"Force balance is a vector sum of zero"},"reason":{"zh":"第 4 步把三个力画成首尾相接的闭合三角形，T₁ + T₂ + W = 0。","en":"Step 4 draws three forces as a closed head-to-tail triangle, T₁ + T₂ + W = 0."},"source":"../math/linear-algebra/vectors/#step4"},
"newton-method:binary-search":{"type":"connection","label":{"zh":"快但挑起点 vs 慢但稳","en":"Fast but picky vs slow but safe"},"reason":{"zh":"第 5 步在同一道开方题上比较两种求根思路：二分法每次只砍一半，牛顿法位数翻倍。","en":"Step 5 compares two root-finding ideas on one square-root problem: bisection halves the bracket, Newton doubles the digits."},"source":"../math/calculus/newton-method/#step5"},
"ode-phase-portraits:derivative":{"type":"foundation","label":{"zh":"变化率写成方程","en":"Rates of change written as equations"},"reason":{"zh":"第 0 步把“数量每单位时间变化多少”写成 x′、y′ 的方程，是导数作为变化率的直接应用。","en":"Step 0 writes “how fast each count changes” as equations for x′ and y′, a direct use of the derivative as a rate."},"source":"../math/calculus/ode-phase-portraits/#step0"},
"ode-phase-portraits:eigen":{"type":"connection","label":{"zh":"平衡点附近可线性化","en":"Linearise near the equilibrium"},"reason":{"zh":"第 2 步找到的平衡点附近，方向场可近似为线性系统，其旋转或收敛由特征值决定。","en":"Near the equilibrium found in step 2 the field can be approximated by a linear system, whose rotation or decay is decided by eigenvalues."},"source":"../math/calculus/ode-phase-portraits/#step2"},
"patterns-sequences:slope":{"type":"foundation","label":{"zh":"恒定增量即斜率","en":"Constant step is a slope"},"reason":{"zh":"每多一个图形总数增加同样的量，折线上的点排成直线，这个增量就是直线的斜率。","en":"Each extra shape adds the same number of sticks, so the points lie on a line and the step is that line's slope."},"source":"../math/algebra/patterns-sequences/#step3"},
"periodic-trends:gaussian":{"type":"connection","label":{"zh":"趋势与例外并存","en":"Trend with scatter"},"reason":{"zh":"趋势线是总体规律，真实数据点绕着它上下散开——这团散开的残差，正态分布就是描述它的标准形状。","en":"The trend line is the overall rule, and real data points scatter around it — that scattered cloud of residuals is exactly what the normal distribution is the standard shape for."},"source":"../chemistry/matter/periodic-trends/#step2"},
"periodic-trends:molecular-shapes":{"type":"application","label":{"zh":"电负性差决定键偶极","en":"Electronegativity differences set bond dipoles"},"reason":{"zh":"键偶极的大小来自两原子的电负性差——电负性是周期趋势，偶极是分子形状的输入：趋势页的数，形状页拿去算极性。","en":"A bond dipole's size comes from the two atoms' electronegativity difference — electronegativity is a periodic trend, and the dipole is molecular shape's input: the trends lesson's numbers are what the shapes lesson computes polarity from."},"source":"../chemistry/matter/periodic-trends/#step0"},
"place-value:patterns-sequences":{"type":"connection","label":{"zh":"每一位都是上一位的 10 倍","en":"Each place is 10 times the last"},"reason":{"zh":"位值依次为 1、10、100…，是一个每次乘 10 的规律；找规律页讲的是每次加同样的量，这里是每次乘同样的数。","en":"Place values 1, 10, 100… follow a rule of multiplying by 10 each time; the patterns page handles a constant added amount, here the amount multiplies."},"source":"../math/arithmetic/place-value/#step5"},
"polygon-angles:unit-circle":{"type":"connection","label":{"zh":"外角和就是转一整圈","en":"Exterior angles make one full turn"},"reason":{"zh":"沿多边形走一圈累计转 360°，这和单位圆上转一周回到起点是同一个事实。","en":"Walking round a polygon turns you through 360°, the same fact as going once round the unit circle back to the start."},"source":"../math/geometry/polygon-angles/#step3"},
"probability:expected-value":{"type":"foundation","label":{"zh":"概率加权平均","en":"A probability-weighted average"},"reason":{"zh":"有了每个结果的概率，才能按概率加权算出长期平均——期望就是这张概率表的加权平均数，是“平均会怎样”的第一个数字。","en":"Once each outcome has a probability, weighting by those probabilities gives the long-run average — the expected value is that probability table's weighted average, the first number answering 'what happens on average'."},"source":"../probability/basics/expected-value/#step0"},
"probability:isomers":{"type":"application","label":{"zh":"计数与组合","en":"Counting and combinatorics"},"reason":{"zh":"骨架计数是组合问题：先生成所有可能，再用规范形式去重。","en":"Counting skeletons is a combinatorics problem: generate every possibility, then remove repeats with a canonical form."},"source":"../chemistry/matter/isomers/#step1"},
"probability:pagerank":{"type":"application","label":{"zh":"随机游走的长期频率","en":"long-run frequency of a random walk"},"reason":{"zh":"随机冲浪者每一步按概率选下一页，长期访问频率收敛到一个分布，这个分布就是 PageRank。","en":"A random surfer picks the next page by probability at each step, and the long-run visit frequencies converge to a distribution: the PageRank."},"source":"../computing/algorithms/pagerank/#step1"},
"real-number-line:unit-circle":{"type":"foundation","label":{"zh":"数轴上的点","en":"Points on the number line"},"reason":{"zh":"单位圆上的角度和坐标（如 √2/2）都是实数；先知道无理数在数轴上有确切位置，才好理解它们。","en":"Angles and coordinates on the unit circle (such as √2/2) are real numbers; knowing irrational numbers have exact places on the line makes them easier to accept."},"source":"../math/arithmetic/real-number-line/#step5"},
"recursion-divide:exp-log":{"type":"application","label":{"zh":"汉诺塔的指数增长","en":"Hanoi's exponential growth"},"reason":{"zh":"汉诺塔每增加一个盘子，步数翻倍再加 1，总数是 2ⁿ−1，这是指数函数的一个具体例子；二分查找则对应对数。","en":"Each extra Hanoi disk doubles the moves and adds 1, giving 2ⁿ−1, a concrete exponential function, while binary search corresponds to the logarithm."},"source":"../computing/algorithms/recursion-divide/#step3"},
"regression-correlation:slope":{"type":"application","label":{"zh":"用斜率读出变化关系","en":"Reading a relation off a slope"},"reason":{"zh":"第 1 步的拟合斜率 m 就是“x 增加 1，y 平均增加多少”，是直线斜率概念在数据上的应用。","en":"The fitted slope m in step 1 is “how much y rises on average per unit of x”, the straight-line slope applied to data."},"source":"../probability/statistics/regression-correlation/#step1"},
"rsa-encryption:hashing":{"type":"connection","label":{"zh":"都依赖单向函数","en":"Both rely on one-way functions"},"reason":{"zh":"第 0 步的“乘易分解难”是一种（假设上的）单向性，与哈希函数“正向易、反向难”的思想同类。","en":"Step 0’s “easy to multiply, hard to factor” is an (assumed) one-way property, the same idea as hash functions being easy forward and hard to reverse."},"source":"../computing/systems/rsa-encryption/#step0"},
"sequences-series:integral":{"type":"connection","label":{"zh":"求和是积分的离散版本","en":"A sum is the discrete version of an integral"},"reason":{"zh":"第 1 步用长方形面积的一半算出 Sₙ，与积分把连续的量累加成面积是同一种“累加成面积”的想法。","en":"Step 1 gets Sₙ as half a rectangle’s area, the same idea as an integral accumulating a continuous quantity into an area."},"source":"../math/algebra/sequences-series/#step1"},
"shortest-path:pagerank":{"type":"connection","label":{"zh":"都在图上累积一个量","en":"Both accumulate a quantity over a graph"},"reason":{"zh":"最短路沿边累加权重得到距离，PageRank 沿边传递重要性；两者都是在有向/加权图上沿边做计算。","en":"Shortest paths add weights along edges to get distances while PageRank passes importance along edges; both compute along edges of a weighted or directed graph."},"source":"../computing/algorithms/shortest-path/#step5"},
"similarity-scaling:pinhole-ratio":{"type":"connection","label":{"zh":"同样是相似三角形","en":"The same similar triangles"},"reason":{"zh":"小孔成像里物与像的比例、影子测高里杆与树的比例，都来自一对相似三角形的对应边成比例。","en":"The object-to-image ratio in a pinhole camera and the stick-to-tree ratio in shadow measuring both come from corresponding sides of similar triangles."},"source":"../math/geometry/similarity-scaling/#step3"},
"simultaneous-equations:slope":{"type":"representation","label":{"zh":"每个方程是一条直线","en":"Each equation is a line"},"reason":{"zh":"每个一次方程画出来是一条直线，斜率相同的两条线平行（D = 0），斜率不同就必有一个交点。","en":"Each linear equation draws a line; equal slopes give parallel lines (D = 0) and different slopes always cross once."},"source":"../math/algebra/simultaneous-equations/#step4"},
"sine:fourier":{"type":"foundation","label":{"zh":"提供频率分量","en":"provides frequency components"},"reason":{"zh":"傅里叶分析以不同频率的正弦、余弦或复指数为分量；每个分量有自己的幅度和相位。","en":"Fourier analysis uses sine, cosine or complex-exponential components at different frequencies, with their own amplitudes and phases."},"source":"../signal/transforms/fourier/#step1"},
"sine:interference":{"type":"application","label":{"zh":"用相位差确定合振幅","en":"uses relative phase to determine resultant amplitude"},"reason":{"zh":"同一点的两列线性简谐波逐时相加；同频等振幅且相对相位固定时，B=2A|cos(δ/2)|。这是一条应用连接，不表示必须先学完另一课程。","en":"Two linear sinusoids add at the same point and time. For fixed relative phase, equal frequency and equal received amplitude, B=2A|cos(δ/2)|. This is an application, not a required course order."},"source":"../physics/waves/interference/#step3"},
"sine:oscillation":{"type":"representation","label":{"zh":"描述理想运动","en":"describes ideal motion"},"reason":{"zh":"无阻尼、无持续外力驱动（回复力仍存在）的理想弹簧振子满足 x″ + (k/m)x = 0，其解为正弦和余弦的组合。","en":"An ideal spring without damping or sustained driving, with its restoring force still present, obeys x″ + (k/m)x = 0, whose solutions combine sine and cosine."},"source":"https://openstax.org/books/university-physics-volume-1/pages/15-1-simple-harmonic-motion","reading":{"title":{"zh":"这是一种表示方式，不是必修箭头","en":"A representation, not a mandatory learning order"},"meaning":{"zh":"正弦／余弦函数描述理想弹簧的位移怎样变化，并不产生运动。圆周投影是看懂这个函数的辅助图像；弹簧块实际沿直线往返，不沿圆周运动。","en":"Sine and cosine describe how an ideal spring’s position changes; they do not cause the motion. Circular projection helps visualize that function. The spring mass travels along a line, not around the circle."},"startNode":"sine","startHint":{"zh":"如果振幅、频率或相位还陌生，可先看正弦与余弦；已经熟悉就直接试投影实验，不必按箭头重新学一遍。","en":"If amplitude, frequency or phase are unfamiliar, revisit sine and cosine first. If familiar, try the projection experiment directly; the arrow does not require repeating a course."},"trail":"motion","tryNode":"oscillation","bounds":{"zh":"这里限定 m、k 为正的理想线性弹簧，无阻尼、无持续驱动，回复力仍然存在。圆点匀速转动，不代表它的投影匀速往返；其他往返运动不一定符合这套模型。","en":"This comparison uses a positive-mass, positive-stiffness ideal linear spring without damping or sustained driving; its restoring force remains. Constant-speed rotation does not make the projection’s velocity constant. Other oscillations need not fit this model."},"source":"https://openstax.org/books/university-physics-volume-1/pages/15-3-comparing-simple-harmonic-motion-and-circular-motion"}},
"sine:seasons-orbit":{"type":"application","label":{"zh":"单位面积受热 ∝ sin h","en":"Heat per area ∝ sin h"},"reason":{"zh":"太阳高度角为 h 时，一束阳光铺在地面上的面积按 1/sin h 变化，所以单位面积的受热与 sin h 成正比，这是夏热冬冷的几何原因。","en":"At Sun altitude h one beam spreads over a ground area of 1/sin h, so heat per unit area is proportional to sin h, the geometric reason summer is warm and winter cold."},"source":"../earth/astronomy/seasons-orbit/#step2"},
"slope:density":{"type":"representation","label":{"zh":"斜率即密度","en":"Slope is density"},"reason":{"zh":"在质量—体积图上，同种材料的点落在过原点的直线上，这条直线的斜率 m/V 就是密度。","en":"On a mass–volume graph, points of one material fall on a line through the origin, and the slope m/V of that line is the density."},"source":"../physics/matter/density/#step1"},
"slope:pinhole-ratio":{"type":"application","label":{"zh":"用同一直线得到相似比","en":"uses one straight line to obtain the ratio"},"reason":{"zh":"以孔心为原点，同一条非竖直光线保持斜率；孔两侧三角形相似，坐标反号给出带符号放大率M=−v/u。光线斜率与放大率不是同一个量，这个关系不是透镜焦距公式。","en":"With the hole as origin, a nonvertical ray keeps one slope. Similar triangles on opposite sides reverse the coordinate sign, giving signed magnification M=−v/u. Ray slope and magnification are different quantities; this is not a lens focal-length formula."},"source":"../physics/optics/pinhole-camera/#geometry-bridge"},
"slope:sequences-series":{"type":"foundation","label":{"zh":"公差就是斜率","en":"The common difference is a slope"},"reason":{"zh":"等差数列的各项落在一条直线上，公差 d 就是这条直线每走一步上升的量，即第 0 步的“每次加 d”。","en":"The terms of an arithmetic sequence lie on a straight line and the common difference d is how much it rises per step, the “add d each time” of step 0."},"source":"../math/algebra/sequences-series/#step0"},
"solid-geometry:integral":{"type":"connection","label":{"zh":"切片累加就是积分的雏形","en":"Adding slices is the seed of integration"},"reason":{"zh":"第 4 步把金字塔切成 k 层并累加“截面积×厚度”，随着 k 增大趋近 H/3，正是定积分的思想。","en":"Step 4 slices a pyramid into k layers and adds “area × thickness”, tending to H/3 as k grows — the idea of a definite integral."},"source":"../math/geometry/solid-geometry/#step4"},
"supply-demand:externalities":{"type":"application","label":{"zh":"价格漏掉了一部分成本","en":"The price leaves out part of the cost"},"reason":{"zh":"供需均衡只反映买卖双方的私人成本与好处；加上外部损害后社会成本线高于供给线，均衡就偏离社会最优。","en":"Supply–demand equilibrium reflects only the buyers’ and sellers’ private costs and benefits; adding external damage lifts the social cost line above supply and moves equilibrium away from the social optimum."},"source":"../math/applied/externalities/#step1"},
"taylor-series:fourier":{"type":"connection","label":{"zh":"局部逼近 vs 整体逼近","en":"Local vs global approximation"},"reason":{"zh":"第 5 步对同一函数并排展示泰勒（一点的高阶导数）与傅里叶（整段区间的积分）两种逼近，收敛行为不同。","en":"Step 5 shows Taylor (higher derivatives at a point) and Fourier (integrals over a stretch) side by side on one function, with different convergence behaviour."},"source":"../math/calculus/taylor-series/#step5"},
"three-views:solid-geometry":{"type":"foundation","label":{"zh":"从平面图回到立体","en":"From flat views back to the solid"},"reason":{"zh":"三视图把立体压成平面图；本页第 0 步让你自己转动立体，看顶点、棱、面如何在不同角度下呈现。","en":"Three views flatten a solid into drawings; step 0 here lets you turn the solid yourself and see how vertices, edges and faces appear from different angles."},"source":"../math/geometry/solid-geometry/#step0"},
"three-views:vectors":{"type":"representation","label":{"zh":"立体的坐标分解","en":"A solid split along axes"},"reason":{"zh":"三视图分别丢掉一个方向的信息（深度、宽度、高度），像把位置向量投影到三个坐标平面上。","en":"Each view discards one direction (depth, width or height), like projecting a position vector onto three coordinate planes."},"source":"../math/geometry/three-views/#step2"},
"unit-circle:complex":{"type":"representation","label":{"zh":"用复数表示旋转","en":"represents rotation with complex numbers"},"reason":{"zh":"单位圆上的点可以写成 cos θ + i sin θ，角度变化对应平面旋转。","en":"A point on the unit circle is cos θ + i sin θ; changing its angle rotates it in the plane."},"source":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/10-5-polar-form-of-complex-numbers"},
"unit-circle:latitude-longitude":{"type":"application","label":{"zh":"纬线长度 ∝ cos 纬度","en":"Parallel length ∝ cos latitude"},"reason":{"zh":"纬度 φ 处的纬线圈半径是 R·cos φ，这正是单位圆上的 cos，所以 1° 经度对应的距离随纬度按 cos φ 缩小。","en":"The parallel at latitude φ has radius R·cos φ, the same cosine as on the unit circle, so the distance for 1° of longitude shrinks like cos φ with latitude."},"source":"../earth/geo/latitude-longitude/#step1"},
"unit-circle:sine":{"type":"foundation","label":{"zh":"定义","en":"defines"},"reason":{"zh":"圆上点的纵、横坐标定义正弦、余弦；匀速转动使这些坐标成为时间函数。","en":"Vertical and horizontal coordinates define sine and cosine; uniform rotation makes them functions of time."},"source":"../math/geometry/trigonometry/#step3"},
"unit-circle:snell":{"type":"application","label":{"zh":"正弦范围判断折射解","en":"sine range tests refraction solutions"},"reason":{"zh":"单位圆给出sin的值域；Snell关系要求sinθ₂=(n₁/n₂)sinθ₁，右侧超过1时没有传播折射光线。光学角从法线起，而不是单位圆默认的水平轴。","en":"The unit circle supplies sine’s range. Snell requires sinθ₂=(n₁/n₂)sinθ₁; above1, no propagating refracted ray exists. Optical angles start at the normal, rather than the unit circle’s usual horizontal axis."},"source":"../physics/optics/reflection-refraction/#critical-proof"},
"vectors:attention-mechanism":{"type":"application","label":{"zh":"向量点积打分","en":"vector dot products as scores"},"reason":{"zh":"注意力用查询向量与键向量的点积衡量相关度，点积的大小由夹角和长度共同决定。","en":"Attention scores relevance with the dot product of a query vector and key vectors; the dot product depends on both the angle and the lengths."},"source":"../computing/ml/attention-mechanism/#step0"},
"vectors:eigen":{"type":"foundation","label":{"zh":"定义特征方向","en":"defines eigen-directions"},"reason":{"zh":"在矩阵变换下寻找只被缩放的非零向量，就得到 Av = λv 的特征向量问题。","en":"Finding nonzero vectors that are only scaled by a matrix leads to the eigenvector equation Av = λv."},"source":"../math/linear-algebra/eigenvectors/#step1"},
"vectors:electric-fields":{"type":"representation","label":{"zh":"场是矢量场","en":"A field is a vector field"},"reason":{"zh":"每一点的 E 都有大小和方向，用箭头表示并按矢量相加。","en":"E has a size and direction at every point, drawn as arrows and added as vectors."},"source":"../physics/electromagnetism/electric-fields/#step0"},
"vectors:embeddings":{"type":"application","label":{"zh":"词作为向量","en":"words as vectors"},"reason":{"zh":"词向量把每个词放进向量空间，相似度用向量的点积和夹角衡量，类比用向量加减完成。","en":"Embeddings place each word in a vector space, with similarity measured by dot products and angles and analogies done by vector addition and subtraction."},"source":"../computing/ml/embeddings/#step1"},
"vectors:magnetic-force":{"type":"representation","label":{"zh":"叉乘给出力的方向","en":"The cross product gives the force direction"},"reason":{"zh":"磁力方向既不沿 v 也不沿 B，而是同时垂直于两者——没有矢量叉乘就说不清这个方向，右手定则就是它的操作版。","en":"The magnetic force points neither along v nor along B, but perpendicular to both — without the vector cross product there is no way to state that direction, and the right-hand rule is its working version."},"source":"../physics/electromagnetism/magnetic-force/#step0"},
"vectors:molecular-shapes":{"type":"representation","label":{"zh":"键偶极是矢量","en":"Bond dipoles are vectors"},"reason":{"zh":"分子极性是各键偶极的矢量和，形状对称时和为零。","en":"Molecular polarity is the vector sum of bond dipoles, which vanishes when the shape is symmetric."},"source":"../chemistry/matter/molecular-shapes/#step4"},
"vectors:vectors":{"type":"representation","label":{"zh":"本页是该节点的互动讲解","en":"This page is an interactive lesson on that node"},"reason":{"zh":"首尾相接与分量加法是同一种加法的两种画法——本页把它们并排演示，落到同一个“向量”节点上。","en":"Head-to-tail and by-components are two drawings of the same addition — this lesson shows them side by side, landing on the single 'vectors' node."},"source":"../math/linear-algebra/vectors/#step1"}
}});
